svg.script:
(function () {
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var bound = [];
  document.querySelectorAll('*').forEach(function (el) {
    var b = [];
    for (var i = 0; i < el.attributes.length; i++) {
      var a = el.attributes[i];
      if (a.name.indexOf('data-bind-') === 0) b.push([a.name.slice(10), a.value]);
    }
    if (b.length) bound.push([el, b]);
  });
  // GitSphere: points on a sphere joined to their nearest neighbours
  var N = 22, pts = [], edges = [], hubs = [3, 8, 11, 15, 19];
  for (var i = 0; i < N; i++) {
    var y = 1 - 2 * (i + 0.5) / N, r = Math.sqrt(1 - y * y), p = i * 2.39996;
    pts.push([Math.cos(p) * r, y, Math.sin(p) * r]);
  }
  var seen = {};
  pts.forEach(function (a, i) {
    pts.map(function (b, j) { return [j, Math.pow(a[0] - b[0], 2) + Math.pow(a[1] - b[1], 2) + Math.pow(a[2] - b[2], 2)]; })
      .filter(function (d) { return d[0] !== i; })
      .sort(function (u, v) { return u[1] - v[1]; }).slice(0, 3)
      .forEach(function (d) { var j = d[0], k = i < j ? i + '-' + j : j + '-' + i; if (!seen[k]) { seen[k] = 1; edges.push([i, j]); } });
  });

  function vals(t) {
    var v = {};
    var a = t * 0.00045, b = 0.42, R = 80, cx = 150, cy = 125;
    var P = pts.map(function (q) {
      var x1 = q[0] * Math.cos(a) + q[2] * Math.sin(a), z1 = -q[0] * Math.sin(a) + q[2] * Math.cos(a);
      var y2 = q[1] * Math.cos(b) - z1 * Math.sin(b), z2 = q[1] * Math.sin(b) + z1 * Math.cos(b);
      return { x: +(cx + R * x1).toFixed(1), y: +(cy + R * y2).toFixed(1), z: z2 };
    });
    function circ(p, r) { return 'M' + (p.x - r).toFixed(1) + ' ' + p.y + 'a' + r + ' ' + r + ' 0 1 0 ' + 2 * r + ' 0a' + r + ' ' + r + ' 0 1 0 ' + -2 * r + ' 0'; }
    var eF = '', eB = '', nF = '', nB = '', hb = '';
    edges.forEach(function (e) {
      var s = 'M' + P[e[0]].x + ' ' + P[e[0]].y + 'L' + P[e[1]].x + ' ' + P[e[1]].y;
      if (P[e[0]].z < 0 && P[e[1]].z < 0) eF += s; else eB += s;
    });
    P.forEach(function (p, i) {
      var hub = hubs.indexOf(i) >= 0;
      if (p.z < 0) { if (hub) hb += circ(p, 5); else nF += circ(p, 3); } else nB += circ(p, hub ? 3 : 2);
    });
    var k = Math.floor((t % 5000) / 1000), h = P[hubs[k]];
    v.gsEdgesFront = eF || 'M0 0'; v.gsEdgesBack = eB || 'M0 0';
    v.gsNodesFront = nF || 'M0 0'; v.gsNodesBack = nB || 'M0 0'; v.gsHubs = hb || 'M0 0';
    v.gsRingX = h.x; v.gsRingY = h.y;
    v.gsLeader = 'M' + h.x + ' ' + h.y + 'L256 ' + (74 + 22 * k);
    v.gsHlY = 65 + 22 * k;
    v.gsProg = +(((t % 5000) / 5000) * 112).toFixed(1);
    v.gsStats = N + ' MODULES · ' + edges.length + ' LINKS';

    return v;
  }
  function apply(t) {
    var v = vals(t);
    bound.forEach(function (pair) {
      pair[1].forEach(function (b) {
        if (b[0] === 'text') pair[0].textContent = v[b[1]];
        else pair[0].setAttribute(b[0], v[b[1]]);
      });
    });
  }
  var start = performance.now(), last = 0;
  function frame(now) {
    if (now - last > 33) { last = now; apply(Math.max(0, now - start)); }
    requestAnimationFrame(frame);
  }
  if (reduce) apply(3500); else requestAnimationFrame(frame);
})();
